  String get legalDataConsentAuditBody =>
      'DVTech வென்ச்சர்ஸ் அனைத்து ஒப்புதல் நிகழ்வுகள் (மானியம், மாற்றம், திரும்பப் பெறுதல்), பயிற்சி பைப்லைன்கள், அநாமதேய சான்றிதழ்கள் மற்றும் மூன்றாம் தரப்பு செயலி அறிவுறுத்தல்கள் ஆகியவற்றின் தணிக்கைத் தடத்தை பராமரிக்கிறது. குத்தகைதாரர் நிர்வாகிகள் நிர்வாக அமைப்புகள் டாஷ்போர்டு வழியாக ஒப்புதல் தணிக்கை அறிக்கையைக் கோரலாம். நாங்கள் வருடாந்திர AI நெறிமுறைகள் மற்றும் தரவு ஆளுமை மதிப்பாய்வுகளை நடத்துகிறோம்.';

