  @override
  String get legalDataConsentCountryKenyaBody =>
      'கென்யா (தரவு பாதுகாப்பு சட்டம் 2019): தானியங்கு செயலாக்கம் மற்றும் விவரக்குறிப்பு வெளிப்படுத்தப்பட வேண்டும்; தரவு பாடங்களுக்கு எதிர்ப்பு தெரிவிக்க உரிமை உண்டு. எந்தவொரு AI பயிற்சி பயன்பாட்டிற்கான ஒப்புதல் தனித்தனியாக பெறப்பட்டு ஆவணப்படுத்தப்படுகிறது.';

  @override
  String get legalDataConsentCountryUSBody =>
      'யுனைடெட் ஸ்டேட்ஸ்: CCPA/CPRA பயனர்கள் தனிப்பட்ட தகவல்களை விற்பனை செய்வதிலிருந்து அல்லது பகிர்வதிலிருந்து விலகுவதற்கான உரிமையைப் பெற்றுள்ளனர். குடை தனிப்பட்ட தகவல்களை விற்காது. சேவை வழங்குவதற்காக AI வழங்குநர்களுடன் தரவைப் பகிர்வது CCPA இன் கீழ் \'விற்பனை\' அல்ல. வெளிப்படையான ஒப்புதல் இல்லாமல் AI வழங்குநர்களுடன் முக்கியமான தனிப்பட்ட தகவல்கள் பகிரப்படாது.';

  @override
  String get legalDataConsentDefaultBody =>
      'இயல்பாக, குடை உங்கள் ஆவணங்கள், வழக்கு விளக்கங்கள், விஷயக் குறிப்புகள், கிளையன்ட் தகவல்தொடர்புகள், AI வினவல்கள் அல்லது AI மாதிரிகளைப் பயிற்றுவிப்பதற்கு, நன்றாக மாற்றுவதற்கு அல்லது மதிப்பீடு செய்வதற்கு பயனர் சமர்ப்பித்த உள்ளடக்கத்தைப் பயன்படுத்தாது. இந்த இயல்புநிலை அனைத்து பயனர்களுக்கும் பொருந்தும் - நுகர்வோர்கள், வழக்கறிஞர் பயனர்கள் மற்றும் நிறுவன வாடகைதாரர்கள் - சந்தா அடுக்கைப் பொருட்படுத்தாமல். அனைத்து குத்தகைதாரர்களுக்கும் உறுதியான பயிற்சி ஒப்புதல் இயல்புநிலையாக முடக்கப்படும், மேலும் வாடகைதாரர் நிர்வாகியால் மட்டுமே செயல்படுத்தப்பட முடியும்.';

