  @override
  String get legalDataConsentNeverUsedBody =>
      'பின்வரும் தரவு எந்த சூழ்நிலையிலும் AI பயிற்சிக்கு பயன்படுத்தப்படாது, இதில் தேர்வு உட்பட: (அ) பில்லிங் தகவல் மற்றும் கட்டண அட்டை தரவு; (ஆ) முழு கிளையன்ட் பெயர்கள், தேசிய அடையாள எண்கள், பாஸ்போர்ட் எண்கள் அல்லது முழுமையான பெயர் குறிப்பிடாமல் பயோமெட்ரிக் தரவு; (c) சிறப்புரிமை வைத்திருப்பவர் வெளிப்படையான எழுத்துப்பூர்வ ஒப்புதலை வழங்காத வரையில், சட்டப்பூர்வ தொழில்முறை சிறப்புரிமையால் பாதுகாக்கப்படும் தகவல்தொடர்புகள்; (ஈ) சட்டப்பூர்வ பிடி அல்லது செயலில் உள்ள வழக்குக்கு உட்பட்ட தரவு; (இ) உடல்நலம் அல்லது மருத்துவ தரவு; (எஃப்) 18 வயதுக்குட்பட்ட பயனர்களின் தரவு.';

