  @override
  String get legalDataConsentRetentionBody =>
      'அநாமதேய பயிற்சி தரவுத்தொகுப்புகள் மாதிரி மேம்பாட்டிற்கு தேவையான காலத்திற்கு தக்கவைக்கப்படுகின்றன, பொதுவாக உருவாக்கப்பட்டதிலிருந்து 24 மாதங்கள். ஃபைன்-டியூனிங் தரவுத்தொகுப்புகளுக்கு 12 மாதங்களுக்குப் பிறகு வெளிப்படையான மறு-ஒப்புதல் தேவை. குத்தகைதாரர் கணக்கு மூடப்பட்டவுடன், அந்த குத்தகைதாரரின் உள்ளடக்கத்திலிருந்து பெறப்பட்ட அனைத்து பயிற்சி தரவுகளும் 60 நாட்களுக்குள் அகற்றப்படும்.';

