  String get legalDataConsentTitle => 'தரவு & AI ஒப்புதல் கொள்கை';

  @override
  String get legalDataConsentWhatIsTrainingBody =>
      'இந்த சூழலில் AI பயிற்சி என்பது உங்கள் தரவைப் பயன்படுத்துவதாகும் - அநாமதேயப்படுத்துதல் மற்றும் புனைப்பெயருக்குப் பிறகு - குடை அம்சங்களைச் செயல்படுத்தும் AI மாதிரிகளின் துல்லியம், பொருத்தம் அல்லது பாதுகாப்பை மேம்படுத்த. எந்தவொரு மூன்றாம் தரப்பினருடனும் அடையாளம் காணக்கூடிய கிளையன்ட் தரவைப் பகிர்வதை இது அர்த்தப்படுத்துவதில்லை. பயிற்சி பைப்லைன்கள் DVTech வென்ச்சர்ஸ் அல்லது அதன் ஒப்பந்தம் செய்யப்பட்ட AI வழங்குநர்களால் தரவு செயலாக்க ஒப்பந்தங்களின் கீழ் இயக்கப்படுகின்றன.';

  @override
  String get legalDataConsentWhatIsTrainingHeading =>
      '2. AI பயிற்சி என்றால் என்ன';

  @override
  String get legalDataConsentWithdrawBody =>
      'கணக்கு அமைப்புகள் அல்லது support@odaflow.com என்ற மின்னஞ்சல் மூலம் உங்கள் ஒப்புதலை எந்த நேரத்திலும் திரும்பப் பெறலாம். திரும்பப் பெறும்போது: (அ) உங்கள் கணக்கிலிருந்து எந்தத் தகவலும் பயிற்சிக் குழாய்க்குள் நுழையாது; (ஆ) ஏற்கனவே பயிற்சியளிக்கப்பட்ட மாதிரியில் இணைக்கப்பட்ட அநாமதேயத் தரவை அந்த மாதிரியிலிருந்து அகற்ற முடியாது (தொழில்நுட்ப ரீதியாக அநாமதேய மொத்த தரவுகளுடன், GDPR ரீசிடல் 26 க்கு இணங்க); (c) உங்கள் தரவைக் கொண்ட ஏதேனும் நிலுவையில் உள்ள பயிற்சித் தொகுதிகள் 30 நாட்களுக்குள் அகற்றப்படும்; (ஈ) 5 வணிக நாட்களுக்குள் மின்னஞ்சலில் பணம் திரும்பப் பெறப்பட்டதற்கான உறுதிப்படுத்தலைப் பெறுவீர்கள்.';

