  @override
  String get legalDisclaimerAINotLawyerBody =>
      'குடையின் AI அமைப்புகள் பொது சட்ட நிறுவனத்தில் பயிற்சி பெற்ற பெரிய மொழி மாதிரிகள் ஆகும். அவர்கள் நடைமுறைச் சான்றிதழ்களை வைத்திருக்கவில்லை, நீதிமன்றத்தில் ஆஜராக முடியாது, எந்தவொரு பார் அசோசியேஷன் அல்லது சட்ட சங்கத்தால் கட்டுப்படுத்தப்படவில்லை, மேலும் ஒரு வழக்கறிஞரைப் போல உங்களுக்கு எந்தக் கடமையும் இல்லை. AI வெளியீடுகள்: உண்மைப் பிழைகள் அல்லது பிரமைகள் இருக்கலாம்; உங்கள் குறிப்பிட்ட உண்மைகளுடன் தொடர்புடைய பொருள் பரிசீலனைகளைத் தவிர்க்கவும்; திருத்தப்பட்ட, ரத்து செய்யப்பட்ட அல்லது ரத்து செய்யப்பட்ட சட்டங்கள் அல்லது வழக்குகளை மேற்கோள் காட்டுங்கள்; சமீபத்திய சட்ட மாற்றங்களை கணக்கில் கொள்ளத் தவறியது; சிக்கலான அல்லது தெளிவற்ற சட்டக் கேள்விகளை தவறாகப் புரிந்துகொள்வது. ஒவ்வொரு AI வெளியீட்டையும் நீங்கள் விசாரணைக்கான தொடக்கப் புள்ளியாகக் கருத வேண்டும், இறுதிப் பதில் அல்ல.';

