  @override
  String get legalDisclaimerNoPrivilegeBody =>
      'குடையின் AI உடனான தகவல்தொடர்புகள் எந்தவொரு அதிகார வரம்பிலும் வழக்கறிஞர்-வாடிக்கையாளர் சிறப்புரிமை அல்லது சட்டப்பூர்வ தொழில்முறை சிறப்புரிமையால் பாதுகாக்கப்படுவதில்லை. சிறப்புரிமையின் கீழ் நீங்கள் பாதுகாக்க உத்தேசித்துள்ள தளத்தில் தகவலைச் சமர்ப்பிக்க வேண்டாம். குடை சந்தை மூலம் உரிமம் பெற்ற வழக்கறிஞரை நீங்கள் ஈடுபடுத்தினால், செயல்படுத்தப்பட்ட தக்கவைப்பு ஒப்பந்தத்தின் கீழ் அந்த வழக்கறிஞருடனான உங்கள் தகவல்தொடர்புகளுடன் சிறப்புரிமை இணைக்கப்படலாம், ஆனால் உங்கள் முந்தைய AI தொடர்புகளுக்கு அல்ல.';

