  @override
  String get legalDisclaimerRegulatoryBody =>
      'DVTech வென்ச்சர்ஸ் ஒரு தொழில்நுட்ப நிறுவனம், ஒழுங்குபடுத்தப்பட்ட சட்ட சேவை வழங்குநர் அல்ல. வக்கீல்கள் ஒழுங்குமுறை ஆணையம் (யுகே), இந்திய பார் கவுன்சில், கென்யாவின் சட்ட சங்கம், எந்த யுஎஸ் ஸ்டேட் பார் அல்லது வேறு எந்த சட்ட ஒழுங்குமுறை அமைப்பும் சட்ட சேவைகளை வழங்க எங்களுக்கு அங்கீகாரம் அளிக்கவில்லை. சட்ட சேவைகள் சட்டம் 2007 (யுகே) அல்லது பிற அதிகார வரம்புகளில் சமமான சட்டத்தில் வரையறுக்கப்பட்டுள்ளபடி ஒழுங்குபடுத்தப்பட்ட சட்ட நடவடிக்கைகளை குடை தளம் வழங்காது.';

  @override
  String get legalDisclaimerRegulatoryHeading => '9. ஒழுங்குமுறை நிலை';

  @override
  String get legalDisclaimerRelianceBody =>
      'நீங்கள் ஒப்புக்கொள்கிறீர்கள்: (அ) உங்களின் சட்டப்பூர்வ உரிமைகள் அல்லது கடமைகளைப் பாதிக்கும் முடிவுகளை எடுக்க AI வெளியீடுகளை மட்டுமே நீங்கள் நம்ப மாட்டீர்கள்; (ஆ) சட்ட நடவடிக்கைகளைத் தொடங்குவதற்கு, பாதுகாப்பதற்கு அல்லது தீர்ப்பதற்கு முன் நீங்கள் சுயாதீனமான தகுதி வாய்ந்த சட்ட ஆலோசனையைப் பெறுவீர்கள்; (இ) சுயாதீன சரிபார்ப்பு இல்லாமல் AI வெளியீடுகளை நீங்கள் நம்பியிருப்பதால் ஏற்படும் எந்தத் தீங்குக்கும் DVTech வென்ச்சர்ஸ் பொறுப்பாகாது. இந்த வரம்பு பொருந்தக்கூடிய சட்டத்தால் அனுமதிக்கப்பட்ட முழு அளவிற்கு பொருந்தும்.';

