  String get legalDisclaimerRelianceHeading => '6. ரிலையன்ஸ் மீதான வரம்பு';

  @override
  String get legalDisclaimerScopeBody =>
      'இந்த மறுப்பு குடை பிளாட்ஃபார்மின் ஒவ்வொரு அம்சத்திற்கும் பொருந்தும், ஆனால் அவை மட்டும் அல்ல: சட்ட சிக்கல் சரிபார்ப்பு, AI கோபிலட், ஆவண ஆய்வு, சட்ட ஆய்வு, விஷய பகுப்பாய்வு, மூலோபாய குறிப்புகள், வரைவு ஆவணங்கள் மற்றும் AI-உருவாக்கிய உள்ளடக்கம். குடை செயல்படும் அனைத்து அதிகார வரம்புகளிலும் (இந்தியா, அமெரிக்கா, கென்யா மற்றும் யுனைடெட் கிங்டம்) அனைத்து பயனர்களுக்கும் - நுகர்வோர், வழக்கறிஞர் பயனர்கள் மற்றும் சட்ட நிறுவன குத்தகைதாரர்களுக்கு இது பொருந்தும்.';

  @override
  String get legalDisclaimerScopeHeading => '1. இந்த மறுப்பின் நோக்கம்';

  @override
  String get legalDisclaimerUniversalBody =>
      'குடை சட்டத் தகவல், ஆவண விளக்கம், பிரச்சினை கண்டறிதல் மற்றும் இடர் பகுப்பாய்வு ஆகியவற்றை வழங்குகிறது. இது ஒரு சட்ட நிறுவனம் அல்ல மற்றும் உரிமம் பெற்ற வழக்கறிஞரை மாற்றாது. உங்கள் சூழ்நிலைக்கு குறிப்பிட்ட சட்ட ஆலோசனைக்கு, உங்கள் அதிகார வரம்பில் உள்ள தகுதி வாய்ந்த வழக்கறிஞரை அணுகவும். AI-உருவாக்கிய உள்ளடக்கம் தகவல் நோக்கங்களுக்காக மட்டுமே வழங்கப்படுகிறது மற்றும் சட்ட ஆலோசனை, சட்டப் பிரதிநிதித்துவம் அல்லது உங்களுக்கும் DVTech வென்ச்சர்ஸுக்கும் இடையே வழக்கறிஞர்-வாடிக்கையாளர் உறவை உருவாக்குவது ஆகியவற்றைக் கொண்டிருக்கவில்லை.';

  @override
