  @override
  String get legalDisclaimerUserResponsibilitiesBody =>
      'தளத்தைப் பயன்படுத்துவதன் மூலம் நீங்கள் பொறுப்பை ஏற்கிறீர்கள்: (அ) உங்களின் குறிப்பிட்ட சூழ்நிலையில் AI வெளியீடுகளின் துல்லியம் மற்றும் பொருந்தக்கூடிய தன்மையை மதிப்பீடு செய்தல்; (ஆ) பொருத்தமான இடங்களில் சுதந்திரமான சட்ட ஆலோசனையைப் பெறுதல்; (c) AI வெளியீடுகளின் உங்கள் பயன்பாடு உங்கள் தொழில்முறை கடமைகளுக்கு (வழக்கறிஞர் பயனர்கள்) இணங்குவதை உறுதி செய்தல்; (ஈ) அங்கீகாரம் இல்லாமல் மூன்றாம் தரப்பு ரகசிய தகவலைச் சமர்ப்பிக்காதது; (இ) உங்கள் கணக்குச் சான்றுகளைப் பாதுகாப்பாக வைத்திருத்தல்.';

