  @override
  String get legalPrivacyAutomatedBody =>
      'சட்டப் பகுப்பாய்வை உருவாக்கவும், சிக்கல்களைக் கண்டறியவும், செயல்களைப் பரிந்துரைக்கவும் குடை AI ஐப் பயன்படுத்துகிறது. இந்த AI வெளியீடுகள் தகவல் மட்டுமே மற்றும் உங்கள் சட்ட உரிமைகள் பற்றிய பிணைப்பு முடிவுகளை உருவாக்காது. மனித மதிப்பாய்வு இல்லாமல் உங்களைப் பற்றி சட்டப்பூர்வ அல்லது அதேபோன்ற குறிப்பிடத்தக்க விளைவைக் கொண்ட முழுமையான தானியங்கு முடிவு எடுக்கப்படாது. மோசடி கண்டறிதலுக்கான எங்கள் AI ஆபத்து-மதிப்பீடு இயங்குதள அணுகலைப் பாதிக்கலாம்; அத்தகைய முடிவை நீங்கள் மனித மதிப்பாய்வைக் கோரலாம்.';

  @override
  String get legalPrivacyAutomatedHeading => '11. தானியங்கு முடிவெடுத்தல்';

  @override
  String get legalPrivacyChangesBody =>
      'இந்த தனியுரிமைக் கொள்கையை நாங்கள் அவ்வப்போது புதுப்பிக்கலாம். மெட்டீரியல் மாற்றங்கள் நடைமுறைக்கு வருவதற்கு குறைந்தது 30 நாட்களுக்கு முன்பு மின்னஞ்சல் மற்றும் ஆப்ஸ் அறிவிப்பு மூலம் அறிவிக்கப்படும். நடைமுறைக்கு வரும் தேதிக்குப் பிறகு இயங்குதளத்தைத் தொடர்ந்து பயன்படுத்துவது, புதுப்பிக்கப்பட்ட கொள்கையை ஏற்றுக்கொள்வதைக் குறிக்கிறது.';

  @override
  String get legalPrivacyChangesHeading => '13. இந்தக் கொள்கையில் மாற்றங்கள்';

  @override
  String get legalPrivacyChildrenBody =>
      'குடை 18 வயதுக்குட்பட்ட நபர்களுக்கு இயக்கப்படவில்லை. நாங்கள் தெரிந்தே குழந்தைகளிடமிருந்து தனிப்பட்ட தகவல்களை சேகரிப்பதில்லை. குழந்தை எங்களிடம் தரவைச் சமர்ப்பித்ததாக நீங்கள் நம்பினால், support@odaflow.com ஐத் தொடர்பு கொள்ளுங்கள், நாங்கள் அதை உடனடியாக நீக்குவோம்.';

  @override
  String get legalPrivacyChildrenHeading => '8. குழந்தைகள்';

  @override
  String get legalPrivacyCollectAccountBody =>
      'கணக்குத் தரவு: மின்னஞ்சல் முகவரி, முழுப் பெயர், தொலைபேசி எண் (விரும்பினால்), வசிக்கும் நாடு மற்றும் கடவுச்சொல் ஹாஷ். வழக்கறிஞர் பயனர்களுக்கு: பார் பதிவு எண், நிறுவனத்தின் பெயர், பயிற்சி பகுதிகள் மற்றும் அதிகார வரம்பு.';

  @override
  String get legalPrivacyCollectBillingBody =>
      'பில்லிங் தரவு: சந்தா திட்டம், கட்டண முறை வகை (கார்டு பிராண்ட், கடைசி நான்கு இலக்கங்கள்), பில்லிங் முகவரி மற்றும் பரிவர்த்தனை வரலாறு. முழு கட்டண அட்டை விவரங்களும் எங்கள் பிசிஐ-டிஎஸ்எஸ்-இணக்கமான கட்டணச் செயலி (ஸ்ட்ரைப்) மூலம் கையாளப்படுகின்றன, மேலும் அவை எங்கள் சேவையகங்களில் சேமிக்கப்படாது.';

  @override
  String get legalPrivacyCollectContentBody =>
      'உள்ளடக்கத் தரவு: சட்ட ஆவணங்கள், வழக்கு விளக்கங்கள், விஷயக் குறிப்புகள், கிளையன்ட் தகவல்தொடர்புகள் மற்றும் தளத்தின் மூலம் நீங்கள் உருவாக்கும் அல்லது சமர்ப்பிக்கும் AI-உருவாக்கிய வெளியீடுகள். இந்த உள்ளடக்கம் சேவையை வழங்குவதற்காக செயலாக்கப்படுகிறது மற்றும் உங்கள் வெளிப்படையான தேர்வு இல்லாமல் AI பயிற்சிக்கு பயன்படுத்தப்படாது.';

  @override
