      'பயன்பாட்டுத் தரவு: பார்வையிட்ட பக்கங்கள், பயன்படுத்தப்பட்ட அம்சங்கள், சமர்ப்பிக்கப்பட்ட AI வினவல்கள், பதிவேற்றப்பட்ட ஆவணங்கள், செலவழித்த நேரம், நிகழ்வுகளைக் கிளிக் செய்தல் மற்றும் அமர்வு பதிவுகள் (ஒப்புதல் வழங்கப்பட்ட இடங்களில்). இந்தத் தரவு முதல் தரப்பு பகுப்பாய்வு மூலம் சேகரிக்கப்படுகிறது.';

  @override
  String get legalPrivacyContactBody =>
      'தரவு பாதுகாப்பு விசாரணைகள்: support@odaflow.com. 10 வணிக நாட்களுக்குள் பதிலளிப்பதை நோக்கமாகக் கொண்டுள்ளோம். எங்கள் பதிலில் நீங்கள் திருப்தியடையவில்லை என்றால், உங்கள் உள்ளூர் தரவுப் பாதுகாப்பு ஆணையத்திடம் புகார் அளிக்க உங்களுக்கு உரிமை உண்டு: UK — ICO (ico.org.uk); EU - உங்கள் தேசிய DPA; இந்தியா — இந்திய தரவு பாதுகாப்பு வாரியம்; கென்யா — தரவு பாதுகாப்பு ஆணையரின் அலுவலகம் (odpc.go.ke).';

