  @override
  String get legalPrivacyControllerBody =>
      'குடை DVTech வென்ச்சர்ஸால் இயக்கப்படுகிறது (\"நாங்கள்\", \"நாங்கள்\", \"எங்கள்\"). நுகர்வோரிடமிருந்து சேகரிக்கப்பட்ட தகவல்களுக்கான தரவுக் கட்டுப்பாட்டாளராகவும், சட்ட நிறுவனம் வாடகைதாரர்கள் சார்பாக நடத்தப்படும் தகவல்களுக்கான தரவுச் செயலியாகவும் நாங்கள் செயல்படுகிறோம். பதிவுசெய்யப்பட்ட முகவரி மற்றும் தரவு பாதுகாப்பு தொடர்பு: support@odaflow.com. GDPR நோக்கங்களுக்காக, எங்கள் EU/UK பிரதிநிதியை அதே முகவரியில் தொடர்பு கொள்ளலாம்.';

  @override
  String get legalPrivacyControllerHeading => '1. நாம் யார்';

  @override
  String get legalPrivacyCookiesBody =>
      'கண்டிப்பாக தேவையான குக்கீகள் (அமர்வு மேலாண்மை, பாதுகாப்பு டோக்கன்கள்) எப்போதும் செயலில் இருக்கும். செயல்பாட்டு குக்கீகள் (மொழி விருப்பம், தீம்) முதல் பயன்பாட்டில் அமைக்கப்பட்டன மற்றும் உலாவி அமைப்புகளில் அழிக்கப்படும். Analytics குக்கீகள் (Vercel, Sentry) குக்கீ பேனர் மூலம் உங்கள் ஒப்புதலுடன் மட்டுமே அமைக்கப்படும். நாங்கள் விளம்பரம் அல்லது குறுக்கு-தள கண்காணிப்பு குக்கீகளைப் பயன்படுத்துவதில்லை.';

  @override
  String get legalPrivacyCookiesHeading => '12. குக்கீகள்';

  @override
  String get legalPrivacyDescription =>
      'குடை உங்கள் தகவலை எவ்வாறு சேகரிக்கிறது, பயன்படுத்துகிறது மற்றும் பாதுகாக்கிறது. இந்தியா, அமெரிக்கா, கென்யா மற்றும் யுனைடெட் கிங்டம் முழுவதும் உள்ள umbrella.okaylegal.ai மற்றும் தொடர்புடைய குடை பயன்பாடுகளின் அனைத்து பயனர்களுக்கும் இந்தக் கொள்கை பொருந்தும்.';

  @override
  String get legalPrivacyLegalBasisBody =>
      'உங்கள் அதிகார வரம்பைப் பொறுத்து பின்வரும் சட்ட அடிப்படைகளின் கீழ் தனிப்பட்ட தரவை நாங்கள் செயலாக்குகிறோம்: (அ) ஒப்பந்தம் - நீங்கள் பதிவுசெய்துள்ள சேவைகளை வழங்க தேவையான செயலாக்கம்; (ஆ) சட்டபூர்வமான நலன்கள் - மோசடி தடுப்பு, மேடை பாதுகாப்பு, தயாரிப்பு மேம்பாடு; (c) ஒப்புதல் - AI பயிற்சி, மார்க்கெட்டிங் மின்னஞ்சல்கள், கண்டிப்பாகத் தேவையான குக்கீகள்; (ஈ) சட்டப்பூர்வ கடமை - பொருந்தக்கூடிய சட்டத்திற்கு இணங்குதல். இந்தியாவைப் பொறுத்தவரை, டிஜிட்டல் தனிநபர் தரவுப் பாதுகாப்புச் சட்டம் 2023 (DPDP சட்டம்) மூலம் செயலாக்கம் நிர்வகிக்கப்படுகிறது. UK/EU க்கு, செயலாக்கமானது UK GDPR மற்றும் EU GDPR உடன் இணங்குகிறது. கென்யாவைப் பொறுத்தவரை, செயலாக்கமானது தரவுப் பாதுகாப்புச் சட்டம் 2019 உடன் இணங்குகிறது. அமெரிக்க பயனர்களுக்கு, CCPA/CPRA உட்பட பொருந்தக்கூடிய மாநில தனியுரிமைச் சட்டங்களுக்கு நாங்கள் இணங்குகிறோம்.';

  @override
  String get legalPrivacyLegalBasisHeading =>
      '2. செயலாக்கத்திற்கான சட்ட அடிப்படைகள்';

  @override
  String get legalPrivacyPolicy => 'தனியுரிமைக் கொள்கை';

  @override
  String get legalPrivacyRetentionBody =>
      'உங்கள் கணக்கு செயலில் இருக்கும் வரை தனிப்பட்ட தரவை நாங்கள் வைத்திருக்கிறோம். கணக்கை நீக்கினால், தனிப்பட்ட தரவை 30 நாட்களுக்குள் நீக்கிவிடுவோம் அல்லது அநாமதேயமாக்குவோம், சட்டத்தின்படி தக்கவைப்பு தேவைப்படும் இடங்கள் தவிர (எ.கா. வரி இணக்கத்திற்காக 7 ஆண்டுகளாகத் தக்கவைக்கப்பட்ட பில்லிங் பதிவுகள், 12 மாதங்களுக்குத் தக்கவைக்கப்பட்ட தணிக்கைப் பதிவுகள்). நிறுவன குத்தகைதாரர்கள் ஆளுகை அமைப்புகள் மூலம் 7 ​​ஆண்டுகள் வரை தனிப்பயன் தக்கவைப்புக் கொள்கைகளை உள்ளமைக்கலாம். தேர்ந்தெடுக்கப்பட்ட உள்ளடக்கத்திலிருந்து பெறப்பட்ட AI-பயிற்சி தரவுத்தொகுப்புகள் எங்கள் தரவு & AI ஒப்புதல் கொள்கையில் உள்ள தக்கவைப்பு அட்டவணைக்கு உட்பட்டது.';

  @override
  String get legalPrivacyRetentionHeading => '6. தக்கவைத்தல்';

  @override
  String get legalPrivacyRightsCCPABody =>
      'கலிஃபோர்னியா (CCPA/CPRA) உரிமைகள்: நாங்கள் சேகரிக்கும் தனிப்பட்ட தகவல்களை அறியும் உரிமை; நீக்க உரிமை; விற்பனையிலிருந்து விலகுவதற்கான உரிமை (நாங்கள் தரவை விற்கவில்லை); உரிமைகளைப் பயன்படுத்துவதற்கான பாகுபாடு இல்லாத உரிமை; தவறான தகவலை திருத்தும் உரிமை; முக்கியமான தனிப்பட்ட தகவல்களைப் பயன்படுத்துவதைக் கட்டுப்படுத்தும் உரிமை.';

  @override
  String get legalPrivacyRightsDPDPBody =>
      'இந்தியாவின் DPDP சட்ட உரிமைகள்: உங்கள் டிஜிட்டல் தனிப்பட்ட தரவை அணுக, திருத்தம் மற்றும் அழிக்கும் உரிமை; குறை தீர்க்கும் உரிமை; உங்கள் சார்பாக உரிமைகளைப் பயன்படுத்த ஒரு நபரை பரிந்துரைக்கும் உரிமை. support@odaflow.com இல் எங்கள் ஒப்புதல் மேலாளரைத் தொடர்புகொள்ளவும்.';

  @override
  String get legalPrivacyRightsGDPRBody =>
      'GDPR / UK GDPR உரிமைகள் (EU மற்றும் UK பயனர்கள்): அணுகல் — உங்கள் தனிப்பட்ட தரவின் நகலைப் பெறுதல்; திருத்தம் - சரியான தவறான தரவு; அழித்தல் - கோரிக்கை நீக்கம் (சட்ட பிடிப்புக்கு உட்பட்டது); கட்டுப்பாடு - ஒரு சர்ச்சை தீர்க்கப்படும் போது வரம்பு செயலாக்கம்; பெயர்வுத்திறன் - உங்கள் தரவை இயந்திரம் படிக்கக்கூடிய வடிவத்தில் பெறவும்; ஆட்சேபனை - முறையான நலன்களின் அடிப்படையில் செயலாக்கத்திற்கு பொருள்; தானியங்கு முடிவுகள் - குறிப்பிடத்தக்க விளைவுகளுடன் முற்றிலும் தானியங்கு முடிவுகளுக்கு உட்பட்டதாக இருக்கக்கூடாது. இந்த உரிமைகளைப் பயன்படுத்த, support@odaflow.comக்கு மின்னஞ்சல் அனுப்பவும் அல்லது பயன்பாட்டில் உள்ள தனியுரிமை அமைப்புகளைப் பயன்படுத்தவும்.';

  @override
  String get legalPrivacyRightsHeading => '9. உங்கள் உரிமைகள்';

  @override
  String get legalPrivacyRightsKenyaBody =>
      'கென்யா தரவு பாதுகாப்பு சட்ட உரிமைகள்: தகவல் பெறும் உரிமை; அணுகல் உரிமை; திருத்தும் உரிமை; அழித்தல் மற்றும் தடுப்பதற்கான உரிமை; பொருள் உரிமை; தரவு பெயர்வுத்திறனுக்கான உரிமை. எங்கள் உள்ளூர் பிரதிநிதியை support@odaflow.com இல் தொடர்பு கொள்ளவும்.';

  @override
  String get legalPrivacySecurityBody =>
      'தொழில்நுட்ப மற்றும் நிறுவன நடவடிக்கைகளை நாங்கள் செயல்படுத்துகிறோம்: TLS 1.2+ போக்குவரத்தில் குறியாக்கம்; ஓய்வு நேரத்தில் AES-256 குறியாக்கம்; பங்கு அடிப்படையிலான அணுகல் கட்டுப்பாடு, குறைந்தபட்ச சலுகைக் கொள்கைகள்; நிர்வாக அணுகலுக்கான பல காரணி அங்கீகாரம்; தானியங்கி பாதிப்பு ஸ்கேனிங்; குறைந்தபட்சம் ஆண்டுதோறும் ஊடுருவல் சோதனை; மற்றும் ஒரு சம்பவ மறுமொழி திட்டம். தனிப்பட்ட தரவு மீறல் உங்கள் உரிமைகளைப் பாதிக்கும் பட்சத்தில், பொருந்தக்கூடிய சட்டத்தின்படி தேவைப்படும் பட்சத்தில், அறிந்த 72 மணி நேரத்திற்குள் உங்களுக்கு அறிவிப்போம்.';

  @override
  String get legalPrivacySecurityHeading => '7. பாதுகாப்பு';

  @override
  String get legalPrivacySharingBody =>
      'உங்கள் தனிப்பட்ட தரவை நாங்கள் விற்க மாட்டோம். நாங்கள் பின்வருமாறு தரவைப் பகிர்கிறோம்:';

  @override
  String get legalPrivacySharingHeading =>
      '5. உங்கள் தரவை யாருடன் பகிர்ந்து கொள்கிறோம்';

  @override
  String get legalPrivacySharingLawyerReview =>
      'வழக்கறிஞர் மதிப்பாய்வு: நீங்கள் ஒரு வழக்கறிஞர் மதிப்பாய்வைக் கோரினால், உங்கள் வழக்குச் சுருக்கம் (நீங்கள் அங்கீகரிக்கும் வரை முழு உள்ளடக்கம் அல்ல) எங்கள் சந்தையில் ஒதுக்கப்பட்ட உரிமம் பெற்ற வழக்கறிஞருடன் பகிரப்படும். பகிரப்பட்டதை நீங்கள் கட்டுப்படுத்துகிறீர்கள்.';

  @override
  String get legalPrivacySharingLegal =>
      'சட்டப்பூர்வ வெளிப்பாடுகள்: சட்டம், நீதிமன்ற உத்தரவு அல்லது ஒழுங்குமுறை ஆணையத்தால் தேவைப்படும்போது நாங்கள் தரவை வெளியிடலாம், மேலும் அவ்வாறு செய்வதிலிருந்து சட்டப்பூர்வமாக தடைசெய்யப்பட்டாலன்றி உங்களுக்கு அறிவிப்போம்.';

  @override
  String get legalPrivacySharingSubprocessors =>
      'துணைச் செயலிகள்: சமமான பாதுகாப்புகள் தேவைப்படும் தரவு செயலாக்க ஒப்பந்தங்களின் கீழ் நாங்கள் மூன்றாம் தரப்பு துணைச் செயலிகளை ஈடுபடுத்துகிறோம். முக்கிய வகைகள்: (i) கிளவுட் உள்கட்டமைப்பு — AWS (உங்கள் நாட்டிற்கு மிக அருகில் உள்ள பகுதியில் தரவு ஹோஸ்ட் செய்யப்பட்டது); (ii) பணம் செலுத்துதல் - பட்டை; (iii) பிழை கண்காணிப்பு - சென்ட்ரி; (iv) பகுப்பாய்வு - வெர்செல்; (v) AI மாதிரி வழங்குநர்கள் - OpenAI மற்றும் DeepSeek (AI பகுப்பாய்வு மற்றும் உட்பொதிப்புகள்); டீப்கிராம் (மீட்டிங் டிரான்ஸ்கிரிப்ஷன்) — வினவல்கள் கிடைக்கும் இடங்களில் பூஜ்ஜிய-தரவு தக்கவைப்பு API ஒப்பந்தங்களின் கீழ் அனுப்பப்படும்; (vi) மின்னஞ்சல் விநியோகம் - மீண்டும் அனுப்பவும்.';

  @override
  String get legalPrivacyTitle => 'தனியுரிமைக் கொள்கை';

  @override
  String get legalPrivacyTransfersBody =>
      'நீங்கள் வசிக்கும் நாட்டிற்கு வெளியே உங்கள் தரவு செயலாக்கப்படலாம். UK/EU இலிருந்து இடமாற்றங்களுக்கு, நாங்கள் ஐரோப்பிய ஆணையம் மற்றும் UK ICO ஆல் அங்கீகரிக்கப்பட்ட நிலையான ஒப்பந்த விதிகளை (SCCs) நம்பியுள்ளோம். இந்தியாவைப் பொறுத்தவரை, இடமாற்றங்கள் எல்லை தாண்டிய தரவு ஓட்டங்களில் DPDP சட்ட விதிகளுக்கு இணங்குகின்றன. கென்யாவைப் பொறுத்தவரை, இடமாற்றங்கள் கென்யா தரவுப் பாதுகாப்புச் சட்டம் 2019 இன் பிரிவு 48 உடன் இணங்குகின்றன. நிறுவன குத்தகைதாரர்கள் ஆளுகை அமைப்புகள் மூலம் தரவு வதிவிடக் கட்டுப்பாடுகளைக் கோரலாம்.';

  @override
  String get legalPrivacyTransfersHeading => '10. சர்வதேச இடமாற்றங்கள்';

  @override
  String get legalPrivacyUseBody =>
      'சேகரிக்கப்பட்ட தரவை நாங்கள் பயன்படுத்துகிறோம்: (அ) உங்கள் கணக்கை உருவாக்கி பராமரிக்கவும்; (ஆ) AI சட்ட பகுப்பாய்வு, விஷய மேலாண்மை, பில்லிங், ஆராய்ச்சி மற்றும் பிற இயங்குதள அம்சங்களை வழங்குதல்; (c) பணம் செலுத்துதல் மற்றும் விலைப்பட்டியல் அனுப்புதல்; (ஈ) பரிவர்த்தனை மின்னஞ்சல்களை அனுப்பவும் (கணக்கு உறுதிப்படுத்தல், கடவுச்சொல் மீட்டமைப்பு, பில்லிங் ரசீதுகள்); (இ) மோசடி, பாதுகாப்பு சம்பவங்கள் மற்றும் துஷ்பிரயோகம் ஆகியவற்றைக் கண்டறிதல், விசாரணை செய்தல் மற்றும் தடுப்பது; (எஃப்) நீதிமன்ற உத்தரவுகள் மற்றும் ஒழுங்குமுறை தேவைகள் உட்பட சட்டப்பூர்வ கடமைகளுக்கு இணங்குதல்; (g) அம்சங்களை மேம்படுத்துவதற்கு (அநாமதேயப்படுத்தப்பட்ட அல்லது புனைப்பெயரிடப்பட்ட தரவை மட்டும் பயன்படுத்தி) ஒட்டுமொத்த இயங்குதளப் பயன்பாட்டை பகுப்பாய்வு செய்யவும்; (எச்) நீங்கள் தேர்வுசெய்த மார்க்கெட்டிங் தகவல்தொடர்புகளை அனுப்பவும் (நீங்கள் எந்த நேரத்திலும் ஒப்புதலை திரும்பப் பெறலாம்).';

  @override
  String get legalPrivacyUseHeading =>
      '4. உங்கள் தகவலை நாங்கள் எவ்வாறு பயன்படுத்துகிறோம்';

  @override
  String get legalPublisherName => 'DVTech Ventures';

  @override
  String get legalStandardDisclaimer =>
      'குடை சட்டத் தகவல், ஆவண விளக்கங்கள், சிக்கல் அடையாளம் மற்றும் இடர் பகுப்பாய்வு ஆகியவற்றை வழங்குகிறது. இது ஒரு சட்ட நிறுவனம் அல்ல மற்றும் உரிமம் பெற்ற வழக்கறிஞரை மாற்றாது. உங்கள் சூழ்நிலைக்கு குறிப்பிட்ட சட்ட ஆலோசனைக்கு, உங்கள் அதிகார வரம்பில் உள்ள தகுதி வாய்ந்த வழக்கறிஞரை அணுகவும்.';

  @override
  String get legalTermsAIOutputsBody =>
      'AI வெளியீடுகள் பெரிய மொழி மாதிரிகளால் உருவாக்கப்படுகின்றன, மேலும் அவை தகவல் நோக்கங்களுக்காக மட்டுமே வழங்கப்படுகின்றன. அவர்கள் சட்ட ஆலோசனையை உருவாக்கவில்லை, வழக்கறிஞர்-வாடிக்கையாளர் உறவை உருவாக்க வேண்டாம், மேலும் தகுதிவாய்ந்த வழக்கறிஞரின் ஆலோசனைக்கு மாற்றாக நம்பக்கூடாது. AI வெளியீடுகள் முழுமையற்றதாகவோ, துல்லியமாகவோ அல்லது காலாவதியாகவோ இருக்கலாம். சட்டங்கள் மற்றும் வழக்குகளுக்கான மேற்கோள்கள் சுயாதீனமாக சரிபார்க்கப்பட வேண்டும். AI வெளியீடுகளின் அடிப்படையில் எடுக்கப்படும் எந்தவொரு செயலுக்கும் நீங்கள் மட்டுமே பொறுப்பு.';

  @override
  String get legalTermsAIOutputsHeading => '9. AI வெளியீடுகளின் தன்மை';

  @override
  String get legalTermsAccountBody =>
      'நீங்கள் துல்லியமான மற்றும் முழுமையான பதிவுத் தகவலை வழங்க வேண்டும் மற்றும் அதை புதுப்பிக்க வேண்டும். உங்கள் நற்சான்றிதழ்களின் இரகசியத்தன்மையை பராமரிப்பது மற்றும் உங்கள் கணக்கின் கீழ் உள்ள அனைத்து செயல்பாடுகளுக்கும் நீங்கள் பொறுப்பாவீர்கள். support@odaflow.com இல் அங்கீகரிக்கப்படாத அணுகலைப் பற்றி உடனடியாக எங்களுக்குத் தெரிவிக்க வேண்டும். இந்த விதிமுறைகளை மீறும் அல்லது சமரசம் செய்யப்பட்டதாக நாங்கள் நியாயமாக சந்தேகிக்கும் கணக்குகளை முடக்குவதற்கான உரிமை எங்களுக்கு உள்ளது.';

  @override
  String get legalTermsAccountHeading => '3. கணக்கு பதிவு';

  @override
  String get legalTermsAgreementBody =>
      'கணக்கை உருவாக்குவதன் மூலம் அல்லது குடை சேவையைப் பயன்படுத்துவதன் மூலம், இந்த விதிமுறைகளுக்குக் கட்டுப்படுவதை ஒப்புக்கொள்கிறீர்கள். நீங்கள் ஒரு சட்ட நிறுவனம், நிறுவனம் அல்லது பிற சட்ட நிறுவனத்தின் சார்பாக தளத்தைப் பயன்படுத்துகிறீர்கள் என்றால், அந்த நிறுவனத்தை பிணைக்க உங்களுக்கு அதிகாரம் இருப்பதாக நீங்கள் பிரதிநிதித்துவப்படுத்துகிறீர்கள். இந்த விதிமுறைகளை நீங்கள் ஏற்கவில்லை என்றால், நீங்கள் தளத்தைப் பயன்படுத்தக்கூடாது. பயனர்கள் குறைந்தது 18 வயது நிரம்பியவராக இருக்க வேண்டும்.';

  @override
  String get legalTermsAgreementHeading => '1. ஏற்றுக்கொள்ளுதல்';

  @override
  String get legalTermsChangesBody =>
      'இந்த விதிமுறைகளை நாங்கள் அவ்வப்போது புதுப்பிக்கலாம். மெட்டீரியல் மாற்றங்கள் நடைமுறைக்கு வருவதற்கு குறைந்தது 30 நாட்களுக்கு முன்பு மின்னஞ்சல் மற்றும் ஆப்ஸ் அறிவிப்பு மூலம் அறிவிக்கப்படும். நடைமுறைக்கு வரும் தேதிக்குப் பிறகு தொடர்ந்து பயன்படுத்தினால் ஏற்றுக்கொள்ளப்படும்.';

  @override
  String get legalTermsChangesHeading => '20. இந்த விதிமுறைகளில் மாற்றங்கள்';

  @override
  String get legalTermsConfidentialityBody =>
      'உங்கள் உள்ளடக்கம் மற்றும் விஷயத் தரவை நாங்கள் ரகசியமாக கருதுகிறோம், மேலும் எங்கள் தனியுரிமைக் கொள்கையில் விவரிக்கப்பட்டுள்ளபடி அல்லது சட்டத்தின்படி தேவைப்படுவதைத் தவிர மூன்றாம் தரப்பினருக்கு வெளியிட மாட்டோம். வாடிக்கையாளர்-ரகசிய தகவல்தொடர்புகள் பொருந்தக்கூடிய தொழில்முறை சிறப்புரிமை விதிகளுக்கு இணங்குவதை வழக்கறிஞர் பயனர்கள் உறுதிசெய்ய வேண்டும். எங்கள் அமைப்புகள் குத்தகைதாரர் தரவை தனிமைப்படுத்த வடிவமைக்கப்பட்டுள்ளன.';

  @override
  String get legalTermsConfidentialityHeading => '13. இரகசியத்தன்மை';

  @override
  String get legalTermsContactBody =>
      'இந்த விதிமுறைகள் பற்றிய கேள்விகள்: support@odaflow.com. DVTech வென்ச்சர்ஸ், பதிவு செய்யப்பட்ட அலுவலக விவரங்கள் கோரிக்கையின் பேரில் கிடைக்கும்.';

  @override
  String get legalTermsContactHeading => '21. தொடர்பு';

  @override
  String get legalTermsDataBody =>
      'எங்களின் தனிப்பட்ட தரவு சேகரிப்பு மற்றும் பயன்பாடு தனியுரிமைக் கொள்கையில் விவரிக்கப்பட்டுள்ளது. AI பயிற்சி மற்றும் பகுப்பாய்வு பயன்பாடுகளுக்கு தரவு மற்றும் AI ஒப்புதல் கொள்கையில் விவரிக்கப்பட்டுள்ளபடி வெளிப்படையான தேர்வு தேவை.';

  @override
  String get legalTermsDataConsentLink => 'தரவு & AI ஒப்புதல் கொள்கை';

  @override
  String get legalTermsDataHeading => '15. தரவு மற்றும் தனியுரிமை';

  @override
  String get legalTermsDataPrivacyLink => 'தனியுரிமைக் கொள்கை';

  @override
  String get legalTermsDefinitionsBody =>
      '\"பிளாட்ஃபார்ம்\" என்றால் umbrella.okaylegal.ai மற்றும் அனைத்து தொடர்புடைய பயன்பாடுகள், APIகள் மற்றும் சேவைகள். \"நுகர்வோர் பயனர்\" என்பது, தங்களின் சொந்த சட்டச் சூழலைப் புரிந்துகொள்வதற்காக இயங்குதளத்தைப் பயன்படுத்தும் இயல்பான நபர். \"வழக்கறிஞர் பயனர்\" என்பது வழக்கறிஞர் OS அம்சங்களைப் பயன்படுத்தி உரிமம் பெற்ற சட்ட வல்லுநர். \"குத்தகைதாரர்\" என்பது சட்ட நிறுவனம் அல்லது உறுதியான சந்தா கொண்ட அமைப்பு. \"AI வெளியீடு\" என்பது குடையின் AI அமைப்புகளால் உருவாக்கப்பட்ட எந்த உரை, பகுப்பாய்வு, வரைவு அல்லது பரிந்துரை. \"மேட்டர்\" என்பது வழக்கறிஞர் OS மூலம் நிர்வகிக்கப்படும் சட்ட வழக்கு அல்லது பரிவர்த்தனை. \"டிவிடெக் வென்ச்சர்ஸ்\" அல்லது \"நாங்கள்\" என்றால் இயங்குதளத்தின் ஆபரேட்டர்.';

  @override
  String get legalTermsDefinitionsHeading => '2. வரையறைகள்';

  @override
  String get legalTermsDescription =>
      'DVTech வென்ச்சர்ஸ் மூலம் இயக்கப்படும் AI-நேட்டிவ் சட்ட தளமான குடையின் உங்கள் பயன்பாட்டை இந்த விதிமுறைகள் நிர்வகிக்கின்றன. தளத்தின் எந்தப் பகுதியையும் பயன்படுத்துவதற்கு முன்பு அவற்றை கவனமாகப் படிக்கவும்.';

  @override
  String get legalTermsDisputeBody =>
      'இந்திய பயனர்கள்: இந்த விதிமுறைகள் இந்தியாவின் சட்டங்களால் நிர்வகிக்கப்படுகின்றன; 1996 ஆம் ஆண்டு பெங்களுருவில் உள்ள நடுவர் மற்றும் சமரசச் சட்டத்தின் கீழ் பிணைப்பு நடுவர் மன்றத்தின் மூலம் சர்ச்சைகள் தீர்க்கப்படும். யுனைடெட் ஸ்டேட்ஸ் பயனர்கள்: டெலாவேரில் அமர்ந்துள்ள AAA வணிக நடுவர் விதிகளின் கீழ் பிணைப்பு மத்தியஸ்தம் மூலம் சர்ச்சைகள் தீர்க்கப்படும்; வகுப்பு நடவடிக்கை விலக்கு பொருந்தும். கென்யா பயனர்கள்: இந்த விதிமுறைகள் கென்யாவின் சட்டங்களால் நிர்வகிக்கப்படுகின்றன; நைரோபி சென்டர் ஃபார் இன்டர்நேஷனல் ஆர்பிட்ரேஷன் (என்சிஐஏ) விதிகளின் கீழ் சர்ச்சைகள் தீர்க்கப்படும். யுனைடெட் கிங்டம் பயனர்கள்: இந்த விதிமுறைகள் ஆங்கில சட்டத்தால் நிர்வகிக்கப்படுகின்றன; சர்ச்சைகள் இங்கிலாந்து மற்றும் வேல்ஸ் நீதிமன்றங்களின் பிரத்தியேக அதிகார வரம்பிற்கு சமர்ப்பிக்கப்படும். எல்லா சந்தர்ப்பங்களிலும், தகுதிவாய்ந்த நீதிமன்றத்திடம் இருந்து அவசரத் தடை நிவாரணம் பெறுவதற்கு எதுவும் உங்களைத் தடுக்காது.';

  @override
  String get legalTermsDisputeHeading =>
      '18. சர்ச்சை தீர்வு மற்றும் ஆளும் சட்டம்';

  @override
  String get legalTermsIPContentBody =>
      'பிளாட்ஃபார்மில் நீங்கள் சமர்ப்பிக்கும் அனைத்து உள்ளடக்கத்தின் உரிமையையும் நீங்கள் வைத்திருக்கிறீர்கள். உள்ளடக்கத்தைச் சமர்ப்பிப்பதன் மூலம், சேவைகளை வழங்குவதற்காக மட்டுமே உங்கள் உள்ளடக்கத்தைச் செயலாக்க, சேமிக்க மற்றும் காட்சிப்படுத்த, உலகளாவிய, ராயல்டி இல்லாத, பிரத்தியேகமற்ற உரிமத்தை DVTech வென்ச்சர்களுக்கு வழங்குகிறீர்கள். தரவு மற்றும் AI ஒப்புதல் கொள்கையின் கீழ் நீங்கள் தேர்வு செய்யும் வரை இந்த உரிமம் AI பயிற்சிக்கு நீட்டிக்கப்படாது.';

  @override
  String get legalTermsIPHeading => '12. அறிவுசார் சொத்து';

  @override
  String get legalTermsIPPlatformBody =>
      'டிவிடெக் வென்ச்சர்ஸ் குடை இயங்குதளம், பிராண்ட், அடிப்படை AI மாதிரிகள் மற்றும் தொழில்நுட்பத்தில் அனைத்து உரிமைகளையும் கொண்டுள்ளது. உங்கள் சந்தா காலத்திற்கு தளத்தைப் பயன்படுத்த, வரையறுக்கப்பட்ட, பிரத்தியேகமற்ற, மாற்ற முடியாத உரிமம் உங்களுக்கு வழங்கப்பட்டுள்ளது.';

  @override
  String get legalTermsIndemnityBody =>
      'தீங்கற்ற DVTech வென்ச்சர்ஸ் மற்றும் அதன் அதிகாரிகள், இயக்குநர்கள், பணியாளர்கள் மற்றும் முகவர்களுக்கு இழப்பீடு வழங்கவும், பாதுகாக்கவும், வைத்திருக்கவும் ஒப்புக்கொள்கிறீர்கள்: (ஆ) பொருந்தக்கூடிய சட்டத்தை நீங்கள் மீறுவது; (இ) மூன்றாம் தரப்பினரின் உரிமைகளை மீறும் நீங்கள் சமர்ப்பிக்கும் உள்ளடக்கம்; (ஈ) தளத்தைப் பயன்படுத்தி உங்கள் வாடிக்கையாளர்களுக்கு நீங்கள் வழங்கும் சட்ட ஆலோசனை அல்லது சேவைகள்.';

  @override
  String get legalTermsIndemnityHeading => '17. இழப்பீடு';

  @override
  String get legalTermsLawyerUsersBody =>
      'வழக்கறிஞர் பயனர்கள் சுதந்திரமான உரிமம் பெற்ற வல்லுநர்கள். வழக்கறிஞர் OS ஐப் பயன்படுத்துவதன் மூலம், உங்கள் அதிகார வரம்பில் செல்லுபடியாகும் பயிற்சிச் சான்றிதழை வைத்திருப்பதையும், பொருந்தக்கூடிய தொழில்முறை நடத்தை விதிகள் மற்றும் பார் விதிமுறைகளுக்கு இணங்க தளத்தைப் பயன்படுத்துவீர்கள் என்பதையும் உறுதிப்படுத்துகிறீர்கள். உங்கள் வாடிக்கையாளர்களுக்கு நீங்கள் வழங்கும் அனைத்து சட்டப் பணிகள் மற்றும் ஆலோசனைகளின் தரம் மற்றும் சட்டபூர்வமான தன்மைக்கு நீங்கள் மட்டுமே பொறுப்பாவீர்கள். குடை கருவிகளை வழங்குகிறது - இது வழக்கறிஞர் பயனர்களின் தொழில்முறை நடத்தையை மேற்பார்வையிடவோ அல்லது உத்தரவாதம் அளிக்கவோ இல்லை.';

  @override
  String get legalTermsLawyerUsersHeading => '11. வழக்கறிஞர் பயனர்கள்';

  @override
  String get legalTermsLiabilityBody =>
      'பொருந்தக்கூடிய சட்டத்தால் அனுமதிக்கப்படும் அதிகபட்ச அளவிற்கு: (அ) இந்த விதிமுறைகள் அல்லது பிளாட்ஃபார்ம் மூலம் எழும் அல்லது தொடர்புடைய எந்தவொரு உரிமைகோரலுக்கும் DVTECH வென்ச்சர்ஸின் மொத்தப் பொறுப்பு. உரிமைகோரலுக்கு முந்தைய 12 மாதங்கள்; (ஆ) மறைமுகமான, தற்செயலான, சிறப்பு, தொடர்ச்சியான, அல்லது தண்டனைக்குரிய சேதங்கள், லாப இழப்பு, தரவு இழப்பு அல்லது நல்லெண்ண இழப்பு ஆகியவற்றிற்கு நாங்கள் பொறுப்பல்ல. அத்தகைய சேதங்களின் சாத்தியக்கூறுகள் மற்றும் வலியுறுத்தப்பட்ட சட்டக் கோட்பாட்டைப் பொருட்படுத்தாமல் நாங்கள் அறிவுறுத்தப்பட்டிருந்தாலும் கூட, இந்த வரம்புகள் பொருந்தும்.';

  @override
  String get legalTermsLiabilityHeading => '16. பொறுப்பு வரம்பு';

  @override
  String get legalTermsNotLawFirmBody =>
      'குடை ஒரு தொழில்நுட்ப தளம், ஒரு சட்ட நிறுவனம் அல்ல. DVTech வென்ச்சர்ஸ் சட்ட ஆலோசனை அல்லது சட்ட பிரதிநிதித்துவத்தை வழங்கவில்லை. தளத்தைப் பயன்படுத்துவது உங்களுக்கும் DVTech வென்ச்சர்ஸுக்கும் இடையே வழக்கறிஞர்-வாடிக்கையாளர் உறவை உருவாக்காது. வழக்கறிஞர் சந்தை உங்களை சுயாதீன உரிமம் பெற்ற வழக்கறிஞர்களுடன் இணைக்கிறது; ஒரு சந்தை வழக்கறிஞருடன் எந்த நிச்சயதார்த்தமும் உங்களுக்கும் அந்த வழக்கறிஞருக்கும் இடையே ஒரு தனித் தக்கவைப்பு ஒப்பந்தத்தால் நிர்வகிக்கப்படுகிறது.';

  @override
  String get legalTermsNotLawFirmHeading => '10. சட்ட நிறுவனம் அல்ல';

  @override
  String get legalTermsOfService => 'சேவை விதிமுறைகள்';

  @override
  String get legalTermsPermittedUseBody =>
      'நீங்கள் தளத்தைப் பயன்படுத்தலாம்: தனிப்பட்ட அல்லது தொழில்முறை பயன்பாட்டிற்காக AI-உருவாக்கப்பட்ட சட்டத் தகவலைப் பெறுதல்; சட்ட விஷயங்கள், வாடிக்கையாளர்கள், பில்லிங் மற்றும் ஆவணங்களை நிர்வகிக்கவும் (வழக்கறிஞர் OS); உரிமம் பெற்ற வழக்கறிஞர்களுடன் இணைக்க வழக்கறிஞர் சந்தையை அணுகவும்; எங்கள் ஆவணப்படுத்தப்பட்ட API மூலம் உங்கள் கணினிகளுடன் இயங்குதளத்தை ஒருங்கிணைக்கவும்.';

  @override
  String get legalTermsPermittedUseHeading => '4. அனுமதிக்கப்பட்ட பயன்பாடு';

  @override
  String get legalTermsProhibitedUseBody =>
      'நீங்கள் செய்யக்கூடாது: (அ) ஒரு வழக்கறிஞர், நீதிபதி அல்லது அரசாங்க அதிகாரியைப் போல் ஆள்மாறாட்டம் செய்வது; (ஆ) வழக்கறிஞர் மறுஆய்வு இல்லாமல் மூன்றாம் தரப்பினருக்கு முறையான சட்ட ஆலோசனையாக AI வெளியீடுகளைப் பயன்படுத்தவும்; (c) சட்டவிரோதமான, அவதூறான அல்லது மோசடியான உள்ளடக்கத்தைச் சமர்ப்பித்தல்; (ஈ) அடிப்படையான AI மாதிரிகள் அல்லது பயிற்சித் தரவைத் தலைகீழாக மாற்ற முயற்சிப்பது, சுரண்டுவது அல்லது பிரித்தெடுப்பது; (இ) எழுத்துப்பூர்வ அனுமதியின்றி தளத்திற்கு மறுவிற்பனை அல்லது துணை உரிம அணுகல்; (f) தரவுப் பாதுகாப்பு, நுகர்வோர் பாதுகாப்பு மற்றும் சட்டத் தொழில் விதிகள் உட்பட பொருந்தக்கூடிய சட்டத்தை மீறும் எந்த வகையிலும் தளத்தைப் பயன்படுத்துதல்; (g) மூன்றாம் தரப்பு அறிவுசார் சொத்துரிமைகளை மீறும் உள்ளடக்கத்தைச் சமர்ப்பிக்கவும்.';

  @override
  String get legalTermsProhibitedUseHeading => '5. தடைசெய்யப்பட்ட பயன்பாடு';

  @override
  String get legalTermsRefundBody =>
      'கணக்கு அமைப்புகளில் எந்த நேரத்திலும் உங்கள் சந்தாவை ரத்து செய்யலாம். தற்போதைய பில்லிங் காலத்தின் முடிவில் ரத்துசெய்தல் நடைமுறைக்கு வரும்; பயன்படுத்தப்படாத நேரத்திற்கு பகுதியளவு பணத்தைத் திரும்பப் பெறுவதில்லை. தவறுதலாக உங்களிடம் கட்டணம் வசூலிக்கப்பட்டுள்ளதாக நீங்கள் நம்பினால், கட்டணம் வசூலித்த 30 நாட்களுக்குள் support@odaflow.com ஐத் தொடர்பு கொள்ளவும். நாங்கள் மதிப்பாய்வு செய்து, பொருத்தமானதாக இருந்தால், எங்கள் விருப்பப்படி விகிதச் சார்பு பணத்தைத் திரும்பப் பெறுவோம்.';

  @override
  String get legalTermsRefundHeading =>
      '8. திரும்பப் பெறுதல் மற்றும் ரத்து செய்தல்';

  @override
  String get legalTermsSeverabilityBody =>
      'இந்த விதிமுறைகளின் எந்த விதியும் செயல்படுத்த முடியாதது என கண்டறியப்பட்டால், மீதமுள்ள விதிகள் முழு பலத்துடன் தொடரும். எந்த உரிமையையும் செயல்படுத்தத் தவறியது அந்த உரிமையை விட்டுக் கொடுப்பது அல்ல. இந்த விதிமுறைகள், தனியுரிமைக் கொள்கை மற்றும் தரவு & AI ஒப்புதல் கொள்கையுடன் சேர்ந்து, உங்களுக்கும் DVTech வென்ச்சர்களுக்கும் இடையே இயங்குதளம் தொடர்பான முழு ஒப்பந்தத்தையும் உருவாக்குகிறது.';

