      'கட்டணத் திட்டங்கள் மாதாந்திர அல்லது வருடாந்திர சுழற்சியில் முன்கூட்டியே பில் செய்யப்படுகின்றன. செக் அவுட்டின் போது விலைகள் உங்கள் உள்ளூர் நாணயத்தில் காட்டப்படும் மற்றும் பொருந்தக்கூடிய வரிகளை உள்ளடக்கியிருக்கலாம். புதுப்பித்தல் தேதிக்கு முன் நீங்கள் ரத்து செய்யாவிட்டால், ஒவ்வொரு பில்லிங் காலத்தின் முடிவிலும் சந்தாக்கள் தானாக புதுப்பிக்கப்படும். பணம் செலுத்தத் தவறினால் அணுகல் இடைநீக்கம் அல்லது நிறுத்தம் ஏற்படலாம்.';

